import {EnglishTts,selectVoice,audioSettings} from './tts.js';
import {uid,normalize,score,parseCSV,rowQuestion,validate,parseText,dayKey,stats,toCSV} from './core.js';
const app=document.querySelector('#app');const icons={home:'⌂',quiz:'◉',sentence:'▧',library:'▤',import:'⇧',stats:'▥',review:'↺',settings:'⚙'};
const demo={id:'demo',name:'A little everyday English',topic:'Everyday English',difficulty:'Cơ bản',demo:true,questions:[{id:'d1',type:'single',prompt:'She ___ to school every day.',options:['go','goes','going','gone'],answer:'B',explanation:'She là ngôi thứ ba số ít, nên động từ thêm -es.'},{id:'d2',type:'single',prompt:'Choose the correct greeting.',options:['Good morning','Good night morning','Morning good','Hello night'],answer:'A',explanation:'“Good morning” là lời chào buổi sáng.'},{id:'d3',type:'sentence',prompt:'Cô ấy học tiếng Anh mỗi ngày.',options:['','','',''],answer:'She studies English every day.',explanation:'Thì hiện tại đơn: she + động từ thêm -s.'}]};
let db;let state={page:'home',tab:'csv',draft:[],session:null,selectedDay:null,search:'',filter:'all',view:'card',motion:'balanced'};let data={sets:[],attempts:[],settings:{motion:'balanced'},session:null};
function openDB(){return new Promise((resolve,reject)=>{let r=indexedDB.open('paper-english',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}function read(){return new Promise((resolve,reject)=>{let r=db.transaction('data').objectStore('data').get('app');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}function save(){return new Promise((resolve,reject)=>{let tx=db.transaction('data','readwrite');tx.objectStore('data').put(data,'app');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}function persist(){save().catch(()=>toast('Không thể lưu dữ liệu. Hãy kiểm tra dung lượng trình duyệt.'))}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const btn=(label,action,cls='')=>`<button class="button ${cls}" data-action="${action}">${label}</button>`;const badge=t=>`<span class="badge">${esc(t)}</span>`;const setBy=id=>data.sets.find(s=>s.id===id);const fmt=s=>`${Math.floor(s/60)} phút`;function toast(msg){let n=document.createElement('div');n.className='toast';n.textContent=msg;document.body.append(n);setTimeout(()=>n.remove(),3000)}function download(name,text,type='text/plain'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
const tts=new EnglishTts({synthesis:window.speechSynthesis,Utterance:window.SpeechSynthesisUtterance,onChange:()=>updateAudioUI()});
let audioScope='';
function audioConfig(){return audioSettings(data.settings)}
function voiceDescription(){if(!tts.supported)return 'Trình duyệt này không hỗ trợ phát âm.';let cfg=audioConfig(),choice=selectVoice(tts.voices,cfg.accent,cfg.voice);if(choice.fallback==='default')return tts.voices.length?'Không có giọng tiếng Anh; thử giọng mặc định của trình duyệt.':'Danh sách giọng chưa sẵn sàng; thử giọng mặc định của trình duyệt.';let label=choice.fallback==='english'?'Đang dùng giọng tiếng Anh thay thế':'Giọng';return label+': '+choice.voice.name+' ('+choice.voice.lang+').'}
function audioText(kind){let s=state.session,q=s?.questions?.[s.index];if(kind==='test')return 'Hello! A little practice every day.';if(!q)return '';if(kind==='quiz')return q.ttsText||q.prompt;if(kind==='sample')return q.ttsText||'';if(kind==='built')return (s.order||[]).map(id=>s.tokens.find(t=>t.id===id)?.word||'').join(' ');if(kind==='correct'&&s.checked[q.id])return q.answer;return ''}
function audioControls(kind,label='Nghe',disabled=false){let cfg=audioConfig();return `<div class="audio-control" data-audio-control><div class="audio-actions"><button class="audio-listen" data-speak="${kind}" ${(!tts.supported||!cfg.enabled||disabled)?'disabled':''} aria-label="${label}"><span class="audio-icon" aria-hidden="true">◖))</span> <span>${label}</span></button><button class="audio-mini" data-speak="${kind}" ${(!tts.supported||!cfg.enabled||disabled)?'disabled':''} aria-label="Phát lại từ đầu">↻ <span>Phát lại</span></button><button class="audio-mini" data-stop-audio aria-label="Dừng phát âm" ${tts.status==='idle'?'disabled':''}>■ <span>Dừng</span></button></div><div class="audio-selectors"><label>Giọng<select data-audio-setting="accent" aria-label="Giọng phát âm"><option value="en-US" ${cfg.accent==='en-US'?'selected':''}>US English</option><option value="en-GB" ${cfg.accent==='en-GB'?'selected':''}>UK English</option></select></label><label>Tốc độ<select data-audio-setting="rate" aria-label="Tốc độ đọc">${[.75,.85,1,1.25].map(n=>`<option value="${n}" ${Number(cfg.rate)===n?'selected':''}>${n}×</option>`).join('')}</select></label></div><div class="audio-status" role="status" aria-live="polite"></div><small class="audio-voice"></small></div>`}
function voiceOptions(){let cfg=audioConfig();let voices=tts.voices.filter(v=>(v.lang||'').replace('_','-').toLowerCase()===cfg.accent.toLowerCase());return '<option value="">Tự động chọn</option>'+voices.map(v=>`<option value="${esc(v.voiceURI)}" ${cfg.voice===v.voiceURI?'selected':''}>${esc(v.name)} (${esc(v.lang)})</option>`).join('')}
function audioSettingsPanel(){let cfg=audioConfig();return `<section class="paper setting-panel audio-panel"><div class="panel-heading"><span class="panel-icon audio-panel-icon">◖))</span><div><span class="eyebrow">LISTEN & LEARN</span><h2>Âm thanh & phát âm</h2></div></div><p>Giọng nói do trình duyệt hoặc thiết bị cung cấp; một số giọng có thể sử dụng dịch vụ của nhà cung cấp.</p><label class="audio-toggle"><input type="checkbox" data-audio-setting="enabled" ${cfg.enabled?'checked':''}> Bật phát âm</label><div class="audio-settings-grid"><label>Giọng ưu tiên<select data-audio-setting="accent"><option value="en-US" ${cfg.accent==='en-US'?'selected':''}>US English</option><option value="en-GB" ${cfg.accent==='en-GB'?'selected':''}>UK English</option></select></label><label>Tốc độ đọc<select data-audio-setting="rate">${[.75,.85,1,1.25].map(n=>`<option value="${n}" ${Number(cfg.rate)===n?'selected':''}>${n}×</option>`).join('')}</select></label></div><label>Giọng cụ thể<select data-audio-setting="voice" id="preferred-voice">${voiceOptions()}</select></label><label class="audio-toggle"><input type="checkbox" data-audio-setting="autoPlay" ${cfg.autoPlay?'checked':''}> Tự đọc khi ghép đúng câu</label>${audioControls('test','Thử giọng')}</section>`}
function updateAudioUI(){if(!app)return;let desc=voiceDescription();app.querySelectorAll('.audio-voice').forEach(el=>el.textContent=desc);app.querySelectorAll('.audio-status').forEach(el=>el.textContent=tts.error||(tts.status==='speaking'?'Đang đọc…':tts.status==='loading'?'Đang chuẩn bị…':''));app.querySelectorAll('[data-audio-control]').forEach(el=>el.classList.toggle('speaking',tts.status==='speaking'));app.querySelectorAll('[data-stop-audio]').forEach(el=>el.disabled=tts.status==='idle');let select=app.querySelector('#preferred-voice');if(select&&document.activeElement!==select)select.innerHTML=voiceOptions()}
window.addEventListener('pagehide',()=>tts.stop());
function streak(){let days=new Set(data.attempts.map(a=>a.day));let d=new Date();let n=0;if(!days.has(dayKey(d)))d.setDate(d.getDate()-1);while(days.has(dayKey(d))){n++;d.setDate(d.getDate()-1)}return n}function setStats(id){return stats(data.attempts.filter(a=>a.setId===id))}function nav(){return [['home','Tổng quan'],['quiz','Quick Quiz'],['sentence','Ghép câu'],['library','Thư viện'],['import','Nhập câu hỏi'],['stats','Thống kê'],['review','Ôn câu sai'],['settings','Cài đặt']].map(([id,label])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icons[id]}</span><span>${label}</span></button>`).join('')}
function layout(content){return `<aside class="sidebar"><div class="brand"><span class="brand-mark">p<span>.</span></span><div><strong>paper english</strong><small>LEARN A LITTLE, DAILY</small></div></div><div class="nav-caption">KHÔNG GIAN HỌC TẬP</div><nav>${nav()}</nav><div class="sidebar-note"><span>✳</span><strong>Tiến bộ mỗi ngày.</strong><p>Chậm một chút cũng được, miễn là bạn vẫn tiếp tục.</p></div><div class="sidebar-bottom">Made for curious minds <span>✳</span></div></aside><main><header class="topbar"><div><span class="eyebrow">YOUR LEARNING SPACE</span><p>Chào mừng trở lại <span>✳</span></p></div><div class="top-right"><span class="streak">✦ &nbsp;${streak()} ngày liên tiếp</span><span class="avatar">P</span></div></header>${content}<footer>© Paper English <span>Học một chút, giỏi hơn mỗi ngày ✳</span></footer></main>`}
function heading(k,title,desc,right=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${desc}</p></div>${right}</div>`}
function home(){let t=stats(data.attempts.filter(a=>a.day===dayKey()));let total=stats(data.attempts);let hour=new Date().getHours();let greeting=hour<12?'Chào buổi sáng':hour<18?'Chào buổi chiều':'Chào buổi tối';let recent=data.sets.slice(0,3);return `${heading('MONDAY TO SUNDAY, A LITTLE EVERY DAY',`${greeting},<br><em>người ham học.</em>`, 'Một chút tiếng Anh hôm nay, thêm tự tin cho ngày mai.',`<div class="date-pill">✳ &nbsp; ${new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'numeric',month:'long'}).format(new Date())}</div>`)}<div class="dashboard-grid"><section class="hero paper"><div class="hero-copy"><span class="tiny-label">YOUR DAILY MOMENT &nbsp; ✦</span><h2>Những điều lớn lao<br>bắt đầu từ <em>một chút.</em></h2><p>Dành vài phút cho bản thân và tiếp tục hành trình tiếng Anh của bạn nhé.</p>${btn('Bắt đầu học &nbsp; ↗','go-quiz','dark')}</div><div class="hero-art"><div class="art-sun">✳</div><div class="art-card one">Aa</div><div class="art-card two">hello<span>✦</span></div><div class="art-dot">✦</div></div><div class="hero-foot"><span>✳ &nbsp; YOUR SPACE TO GROW</span><span>01 / 06</span></div></section><section class="daily paper"><div class="section-top"><span class="tiny-label">TODAY'S FOCUS</span><span>✳</span></div><h3>Mỗi ngày<br>một chút.</h3><p>Mục tiêu nhỏ, tiến bộ lớn.</p><div class="daily-ring"><div><strong>${t.total}</strong><small>/ 10 câu</small></div></div><div class="progress"><i style="width:${Math.min(100,t.total*10)}%"></i></div><small>${t.total>=10?'Bạn đã đạt mục tiêu hôm nay!':'Cùng hoàn thành 10 câu hôm nay nhé.'}</small></section></div><div class="section-heading"><div><span class="eyebrow">A LITTLE PROGRESS EVERY DAY</span><h2>Góc học tập của bạn <span>✳</span></h2></div><span class="muted">Hôm nay, ${dayKey()}</span></div><div class="stat-row"><div class="stat paper"><span>✎</span><div><small>CÂU ĐÃ LÀM HÔM NAY</small><strong>${t.total}<em> câu</em></strong></div></div><div class="stat paper"><span>◎</span><div><small>ĐỘ CHÍNH XÁC</small><strong>${t.accuracy}<em>%</em></strong></div></div><div class="stat paper"><span>◷</span><div><small>THỜI GIAN HỌC</small><strong>${Math.floor(total.seconds/60)}<em> phút</em></strong></div></div><div class="stat paper"><span>✦</span><div><small>CHUỖI NGÀY HỌC</small><strong>${streak()}<em> ngày</em></strong></div></div></div><div class="section-heading"><div><span class="eyebrow">PICK UP WHERE YOU LEFT OFF</span><h2>Hôm nay học gì? <span>✳</span></h2></div><button class="link" data-page="library">Xem thư viện &nbsp; ↗</button></div><div class="module-grid"><button class="module lavender" data-page="quiz"><span class="module-icon">◉</span><span class="module-arrow">↗</span><small>01 / PRACTICE</small><strong>Quick Quiz</strong><p>Một vài câu hỏi, thật nhiều điều mới.</p><span class="module-bottom">BẮT ĐẦU &nbsp; →</span></button><button class="module peach" data-page="sentence"><span class="module-icon">▧</span><span class="module-arrow">↗</span><small>02 / BUILD</small><strong>Ghép câu</strong><p>Chọn từng từ, tạo nên câu chuyện.</p><span class="module-bottom">BẮT ĐẦU &nbsp; →</span></button><button class="module mint" data-page="library"><span class="module-icon">▤</span><span class="module-arrow">↗</span><small>03 / YOUR COLLECTION</small><strong>Thư viện</strong><p>Tất cả bài học của bạn ở đây.</p><span class="module-bottom">KHÁM PHÁ &nbsp; →</span></button></div><div class="section-heading"><div><span class="eyebrow">YOUR LITTLE LIBRARY</span><h2>Bộ đề gần đây <span>✳</span></h2></div><button class="link" data-page="import">+ Nhập bộ đề</button></div><div class="recent-list paper">${recent.length?recent.map(s=>`<button data-open="${s.id}" class="recent"><span class="recent-icon">▤</span><span><strong>${esc(s.name)}</strong><small>${esc(s.topic)} · ${s.questions.length} câu hỏi ${s.demo?'· DEMO':''}</small></span><span>↗</span></button>`).join(''):'<p>Chưa có bộ đề. Hãy nhập bộ đề đầu tiên của bạn.</p>'}</div>`}
function library(){let sets=data.sets.filter(s=>(s.name+' '+s.topic).toLowerCase().includes(state.search.toLowerCase())&&(state.filter==='all'||s.questions.some(q=>q.type===state.filter)));return `${heading('YOUR COLLECTION','Thư viện bài học','Mọi bộ đề của bạn, được giữ gọn gàng ở đây.',btn('+ Nhập bộ đề','go-import','dark'))}<div class="toolbar"><label class="search">⌕ <input id="search" placeholder="Tìm bộ đề hoặc chủ đề..." value="${esc(state.search)}"></label><select id="filter"><option value="all">Tất cả loại bài</option><option value="single" ${state.filter==='single'?'selected':''}>Quiz</option><option value="sentence" ${state.filter==='sentence'?'selected':''}>Ghép câu</option></select><button class="button" data-action="toggle-view">${state.view==='card'?'☷ Danh sách':'▦ Thẻ'}</button></div><div class="library-grid ${state.view==='list'?'list':''}">${sets.map((s,i)=>{let st=setStats(s.id);return `<article class="library-card paper"><div class="section-top"><span class="set-icon c${i%4}">▤</span>${s.demo?badge('DEMO'):badge(s.difficulty||'BÀI HỌC')}</div><h3>${esc(s.name)}</h3><p>${esc(s.topic||'Chưa phân loại')} · ${s.questions.length} câu hỏi</p><div class="card-metrics"><span>${st.total} lượt trả lời</span><strong>${st.accuracy}% chính xác</strong></div><div class="progress"><i style="width:${st.accuracy}%"></i></div><div class="card-actions"><button class="button" data-open="${s.id}">Mở bộ đề ↗</button><button class="icon-button" aria-label="Sao chép bộ đề" data-duplicate="${s.id}">⧉</button><button class="icon-button" aria-label="Xóa bộ đề" data-delete="${s.id}">×</button></div></article>`}).join('')||'<div class="empty paper">Chưa tìm thấy bộ đề nào. Hãy thử từ khóa khác hoặc nhập bộ đề mới.</div>'}</div>`}
function detail(){let s=setBy(state.detail);if(!s)return library();return `${heading('YOUR COLLECTION / BỘ ĐỀ',esc(s.name),`${esc(s.topic)} · ${s.questions.length} câu hỏi`,btn('← Thư viện','go-library'))}<div class="detail-actions">${btn('Bắt đầu Quiz','start-detail','dark')}${btn('Thêm câu hỏi','add-detail')}${btn('Xuất CSV','export-csv')}${btn('Xuất JSON','export-set')}</div><div class="question-list">${s.questions.map((q,i)=>`<article class="paper question-row"><div><span class="badge">${i+1} · ${esc(q.type)}</span><h3>${esc(q.prompt)}</h3><p>Đáp án: <strong>${esc(q.answer)}</strong> ${q.explanation?'· '+esc(q.explanation):''}</p></div><div><button class="icon-button" data-edit-question="${q.id}" aria-label="Sửa câu hỏi">✎</button><button class="icon-button" data-remove-question="${q.id}" aria-label="Xóa câu hỏi">×</button></div></article>`).join('')}</div>`}
function setup(mode){let eligible=data.sets.filter(s=>s.questions.some(q=>mode==='sentence'?q.type==='sentence':q.type!=='sentence'));return `${heading(mode==='sentence'?'MAKE A SENTENCE':'LET’S PRACTICE',mode==='sentence'?'Ghép một câu thật hay.':'Sẵn sàng luyện tập?',mode==='sentence'?'Chọn bộ đề và sắp xếp những mảnh từ.':'Chọn bộ đề và thiết lập buổi học của bạn.')}${eligible.length?`<div class="setup paper"><label>Bộ đề<select id="set-choice">${eligible.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label>${mode==='quiz'?`<div class="form-grid"><label>Số câu<input id="count" type="number" min="1" value="10"></label><label>Chế độ<select id="mode"><option value="practice">Practice · Xem lời giải từng câu</option><option value="test">Test · Chấm khi nộp</option></select></label><label>Thứ tự<select id="order"><option value="ordered">Theo thứ tự</option><option value="random">Xáo trộn</option></select></label></div>`:''}${btn('Bắt đầu ngay &nbsp; ↗',mode==='sentence'?'start-sentence':'start-quiz','dark')}</div>`:`<div class="empty paper">Chưa có câu hỏi phù hợp. ${btn('Nhập câu hỏi','go-import')}</div>`}${data.session?`<div class="resume paper"><div><strong>Bạn có một bài đang học dở</strong><p>Tiếp tục từ câu ${data.session.index+1}.</p></div>${btn('Tiếp tục','resume','dark')}</div>`:''}`}
function start(setId,kind,questions,mode='practice'){tts.stop();let qs=questions||setBy(setId).questions.filter(q=>kind==='sentence'?q.type==='sentence':q.type!=='sentence');state.session={setId,kind,questions:structuredClone(qs),index:0,answers:{},checked:{},mode,started:Date.now(),questionStarted:Date.now(),marked:[],order:[]};data.session=state.session;persist();render()}
function record(q,answer,correct){let s=state.session;if(s.checked[q.id])return;let now=Date.now();data.attempts.push({id:uid(),questionId:q.id,setId:s.setId,topic:q.topic||setBy(s.setId)?.topic||'',kind:s.kind,answer,correct,day:dayKey(),at:now,seconds:Math.min(300,Math.max(0,Math.round((now-s.questionStarted)/1000)))});s.checked[q.id]=true;persist()}
function quiz(){let s=state.session;if(!s||s.kind!=='quiz')return setup('quiz');if(s.finished)return results();let q=s.questions[s.index],a=s.answers[q.id]??(q.type==='multi'?[]:'');let checked=s.checked[q.id];return `${heading('A LITTLE PRACTICE','Từng câu một, nhé.','Cứ bình tĩnh. Bạn đang làm rất tốt.',btn('Thoát bài học','exit-session'))}<div class="quiz-layout"><div class="quiz-main paper"><div class="quiz-top"><span class="badge">CÂU ${s.index+1} / ${s.questions.length}</span><button class="link" data-action="mark">${s.marked.includes(q.id)?'★ Đã đánh dấu':'☆ Đánh dấu'}</button></div><div class="progress"><i style="width:${(s.index+1)/s.questions.length*100}%"></i></div><div class="question-content"><div class="eyebrow">${esc(q.type.toUpperCase())} · ${s.mode==='test'?'TEST MODE':'PRACTICE MODE'}</div><h2>${esc(q.prompt)}</h2>${audioControls('quiz','Nghe câu hỏi')}${['single','multi','truefalse'].includes(q.type)?`<div class="options">${q.options.map((o,i)=>o?`<button class="answer ${Array.isArray(a)?a.includes('ABCD'[i])?'selected':'':a==='ABCD'[i]?'selected':''} ${checked&&s.mode==='practice'&&String(q.answer).split(/[|,]/).includes('ABCD'[i])?'correct':''}" data-answer="${'ABCD'[i]}" ${checked?'disabled':''}><span>${'ABCD'[i]}</span>${esc(o)} ${checked&&String(q.answer).split(/[|,]/).includes('ABCD'[i])?'✓':''}</button>`:'').join('')}</div>`:`<label>Câu trả lời<input id="answer-input" value="${esc(a)}" ${checked?'disabled':''} placeholder="Nhập câu trả lời của bạn..."></label>`}${checked&&s.mode==='practice'?`<div class="explanation ${score(q,a)?'success':'wrong'}"><strong>${score(q,a)?'✓ Chính xác!':'↺ Cùng xem lại nhé.'}</strong><p>Đáp án: ${esc(q.answer)}. ${esc(q.explanation)}</p></div>`:''}</div><div class="quiz-controls">${btn('← Câu trước','prev',s.index?'':'disabled')}${s.mode==='practice'&&!checked?btn('Kiểm tra','check','dark'):''}${btn(s.index===s.questions.length-1?'Nộp bài':'Câu tiếp →','next','dark')}</div></div><aside class="quiz-side paper"><span class="eyebrow">YOUR PROGRESS</span><h3>Hành trình nhỏ.</h3><p>Chọn một số để chuyển câu.</p><div class="number-grid">${s.questions.map((q,i)=>`<button class="number ${i===s.index?'current':''} ${s.answers[q.id]!==undefined?'done':''}" data-jump="${i}">${i+1}</button>`).join('')}</div>${btn('Nộp bài','finish')}</aside></div>`}
function results(){let s=state.session,answered=s.questions.filter(q=>s.answers[q.id]!==undefined&&String(s.answers[q.id]).trim()!==''),correct=answered.filter(q=>score(q,s.answers[q.id]));return `${heading('SESSION COMPLETE','Bạn đã hoàn thành!','Mỗi câu trả lời là một bước tiến nhỏ.')}<div class="result paper">${!s.celebrated?`<div class="paper-confetti" aria-hidden="true">${Array.from({length:12},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div>`:''}<div class="result-score">${answered.length?Math.round(correct.length/answered.length*100):0}<span>%</span></div><h2>Một buổi học thật đáng tự hào.</h2><p>${correct.length} đúng · ${answered.length-correct.length} sai · ${s.questions.length-answered.length} bỏ qua</p><div class="detail-actions">${btn('Làm lại câu sai','retry-wrong','dark')}${btn('Về tổng quan','close-result')}</div></div><div class="question-list">${s.questions.map(q=>`<div class="question-row paper"><div><span class="badge">${s.answers[q.id]===undefined?'BỎ QUA':score(q,s.answers[q.id])?'✓ ĐÚNG':'↺ CẦN ÔN'}</span><h3>${esc(q.prompt)}</h3><p>Bạn chọn: ${esc(s.answers[q.id]??'—')} · Đáp án: ${esc(q.answer)}</p><p>${esc(q.explanation)}</p></div></div>`).join('')}</div>`}
function sentence(){let s=state.session;if(!s||s.kind!=='sentence')return setup('sentence');if(s.finished)return results();let q=s.questions[s.index];if(!s.tokens||s.tokenQuestion!==q.id){s.tokens=q.answer.match(/\S+/g).map((word,i)=>({id:i,word})).sort(()=>Math.random()-.5);s.order=[];s.tokenQuestion=q.id}let selected=s.order.map(id=>s.tokens.find(t=>t.id===id));return `${heading('MAKE A SENTENCE','Ghép từng mảnh từ.','Chạm vào từ để tạo câu; chạm lại để bỏ từ.',btn('Thoát bài học','exit-session'))}<div class="sentence-card paper"><div class="quiz-top"><span class="badge">CÂU ${s.index+1} / ${s.questions.length}</span><span>✳</span></div><h2>${esc(q.prompt)}</h2>${q.ttsText?audioControls('sample','Nghe câu mẫu'):''}<p>YOUR ANSWER</p><div class="dropzone" id="answer-zone">${selected.length?selected.map(t=>`<button class="word selected-word" draggable="true" data-token-remove="${t.id}" data-drag-id="${t.id}">${esc(t.word)}</button>`).join(''):'<span>Kéo hoặc chạm vào từ bên dưới...</span>'}</div>${audioControls('built','Nghe câu đã ghép',!selected.length)}<p>WORD BANK</p><div class="word-bank">${s.tokens.filter(t=>!s.order.includes(t.id)).map(t=>`<button class="word" draggable="true" data-token-add="${t.id}" data-drag-id="${t.id}">${esc(t.word)}</button>`).join('')}</div>${s.checked[q.id]?`<div class="explanation ${score(q,s.answers[q.id])?'success':'wrong'}"><strong>${score(q,s.answers[q.id])?'✓ Chính xác!':'↺ Cùng thử lại sau nhé.'}</strong><p>${esc(q.answer)} · ${esc(q.explanation)}</p>${audioControls('correct','Nghe câu đúng')}</div>`:''}<div class="quiz-controls">${btn('↶ Hoàn tác','undo')}${btn('Đặt lại','reset-words')}${btn('Gợi ý','hint')}${s.checked[q.id]?btn(s.index===s.questions.length-1?'Xem kết quả':'Câu tiếp →','next-sentence','dark'):btn('Kiểm tra','check-sentence','dark')}</div></div>`}
function importer(){return `${heading('MAKE IT YOURS','Mang bài học vào đây.','Nhập câu hỏi từ CSV, văn bản hoặc tạo thủ công.')}<div class="tabs">${[['csv','CSV'],['text','Dán văn bản'],['manual','Tạo thủ công']].map(([id,l])=>`<button class="tab ${state.tab===id?'active':''}" data-tab="${id}">${l}</button>`).join('')}</div><div class="import-layout"><section class="paper import-panel"><label>Tên bộ đề<input id="set-name" placeholder="Ví dụ: Everyday English" value="${esc(state.importName||'')}"></label><div class="form-grid"><label>Chủ đề<input id="set-topic" placeholder="Ví dụ: Ngữ pháp" value="${esc(state.importTopic||'')}"></label><label>Mức độ<select id="set-difficulty"><option>Cơ bản</option><option>Trung bình</option><option>Nâng cao</option></select></label></div>${state.tab==='csv'?`<label class="upload" id="upload-zone"><span>⇧</span><strong>Thả file CSV vào đây</strong><small>hoặc nhấn để chọn file · UTF-8</small><input id="file" type="file" accept=".csv,text/csv" hidden></label><p class="hint">Cột hỗ trợ: type, question/prompt, option_a–d, correct_answer, explanation, topic, difficulty.</p>${btn('Tải CSV mẫu','sample-csv')}`:state.tab==='text'?`<label>Nội dung câu hỏi<textarea id="pasted" rows="12" placeholder="Q: She ___ to school every day.&#10;A. go&#10;B. goes&#10;ANSWER: B&#10;EXPLANATION: She là ngôi thứ ba số ít."></textarea></label>${btn('Phân tích văn bản','parse-text','dark')}`:`<div class="form-grid"><label>Loại câu hỏi<select id="manual-type"><option value="single">Một đáp án</option><option value="multi">Nhiều đáp án</option><option value="truefalse">True / False</option><option value="blank">Điền từ</option><option value="sentence">Ghép câu</option></select></label><label>Đáp án<input id="manual-answer" placeholder="B hoặc câu hoàn chỉnh"></label></div><label>Câu hỏi / gợi ý<textarea id="manual-prompt" rows="3"></textarea></label><div class="form-grid">${['A','B','C','D'].map(x=>`<label>Lựa chọn ${x}<input id="opt-${x}"></label>`).join('')}</div><label>Giải thích<input id="manual-explanation"></label>${btn('Thêm vào danh sách','add-manual','dark')}`}<div class="import-footer">${state.appendTo?`Thêm vào: <strong>${esc(setBy(state.appendTo)?.name)}</strong>`:''}</div></section><aside class="paper preview"><div class="section-top"><div><span class="eyebrow">READY TO LEARN</span><h3>Xem trước</h3></div>${badge(state.draft.length+' CÂU')}</div><p>Kiểm tra và chỉnh sửa trước khi lưu.</p>${state.draft.length?state.draft.map((q,i)=>`<div class="preview-row"><div><strong>${i+1}. ${esc(q.prompt||'Chưa có câu hỏi')}</strong><small>${validate(q).length?'⚠ '+esc(validate(q).join(' · ')):'✓ Hợp lệ · '+esc(q.type)}</small></div><button class="icon-button" data-draft-edit="${i}" aria-label="Sửa">✎</button><button class="icon-button" data-draft-delete="${i}" aria-label="Xóa">×</button></div>`).join(''):'<div class="preview-empty">✳<br>Những câu hỏi của bạn sẽ xuất hiện ở đây.</div>'}${btn('Lưu bộ đề','save-import','dark wide')}</aside></div>`}
function statistics(){let st=stats(data.attempts),days=[...new Set(data.attempts.map(a=>a.day))].sort().reverse(),day=state.selectedDay||dayKey(),ds=stats(data.attempts.filter(a=>a.day===day));let cells=Array.from({length:365},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(364-i));let k=dayKey(d),n=data.attempts.filter(a=>a.day===k).length;return `<button class="heat h${Math.min(4,n)}" data-day="${k}" title="${k}: ${n} lượt" aria-label="${k}: ${n} lượt trả lời"></button>`}).join('');return `${heading('YOUR LEARNING STORY','Nhìn lại hành trình.','Những con số nhỏ kể câu chuyện tiến bộ của bạn.')}<div class="stat-row"><div class="stat paper"><span>✎</span><div><small>LƯỢT TRẢ LỜI</small><strong>${st.total}</strong></div></div><div class="stat paper"><span>✓</span><div><small>CÂU ĐÚNG</small><strong>${st.correct}</strong></div></div><div class="stat paper"><span>◎</span><div><small>ĐỘ CHÍNH XÁC</small><strong>${st.accuracy}%</strong></div></div><div class="stat paper"><span>◷</span><div><small>THỜI GIAN HỌC</small><strong>${fmt(st.seconds)}</strong></div></div></div><div class="analytics-grid"><section class="paper chart"><span class="eyebrow">A YEAR OF LITTLE STEPS</span><h3>Lịch học 365 ngày</h3><p>Chọn một ô để xem chi tiết ngày học.</p><div class="heatmap">${cells}</div><div class="legend">Ít hơn <i class="h0"></i><i class="h1"></i><i class="h2"></i><i class="h3"></i><i class="h4"></i> Nhiều hơn</div></section><section class="paper chart"><span class="eyebrow">DAILY DETAIL</span><h3>${esc(day)}</h3><p>${ds.total} lượt trả lời · ${ds.correct} đúng · ${ds.total-ds.correct} sai</p><div class="big-number">${ds.accuracy}<small>%</small></div><p>${fmt(ds.seconds)} học tập · ${ds.unique} câu hỏi khác nhau</p></section></div><div class="paper chart"><span class="eyebrow">YOUR ACTIVITY</span><h3>Hoạt động gần đây</h3>${days.length?days.slice(0,10).map(d=>{let n=stats(data.attempts.filter(a=>a.day===d));return `<button class="activity-row" data-day="${d}"><span>${d}</span><span>${n.total} lượt</span><strong>${n.accuracy}%</strong></button>`}).join(''):'<p>Chưa có dữ liệu học tập. Hãy bắt đầu một bài học nhé.</p>'}<p class="hint">Một lượt trả lời được ghi khi kiểm tra hoặc nộp bài. Accuracy = lượt đúng / lượt đã trả lời. Thời gian là thời gian trên câu, tối đa 5 phút mỗi lượt; ngày theo Asia/Ho_Chi_Minh. Chuỗi tính theo ngày có ít nhất một lượt trả lời.</p></div>`}
function review(){let latest=new Map();data.attempts.forEach(a=>latest.set(a.questionId,a));let wrong=[...latest.values()].filter(a=>!a.correct).map(a=>({a,q:data.sets.flatMap(s=>s.questions).find(q=>q.id===a.questionId)})).filter(x=>x.q);return `${heading('A CHANCE TO GROW','Ôn lại một chút.','Sai là một phần tự nhiên của việc học.')}${wrong.length?`<div class="question-list">${wrong.map(({a,q})=>`<article class="question-row paper"><div>${badge(q.type)}<h3>${esc(q.prompt)}</h3><p>Đáp án: ${esc(q.answer)} · ${esc(q.explanation)}</p></div><button class="button" data-review="${q.id}">Ôn lại ↗</button></article>`).join('')}</div>`:'<div class="empty paper">✳<h3>Chưa có câu cần ôn.</h3><p>Những câu trả lời sai sẽ xuất hiện tại đây.</p></div>'}`}
function settings(){let motion=data.settings.motion||'balanced';let descriptions={minimal:'Chuyển động được rút gọn để bạn tập trung vào nội dung.',balanced:'Chuyển động mềm mại, vừa đủ cho trải nghiệm hằng ngày.',playful:'Các mảnh giấy bật nảy rõ hơn khi bạn tương tác.'};return `${heading('YOUR SPACE, YOUR PACE','Một góc theo cách bạn.','Điều chỉnh chuyển động và giữ dữ liệu học tập an toàn.')}<div class="settings-layout"><div class="settings-column"><section class="paper setting-panel motion-panel"><div class="panel-heading"><span class="panel-icon lavender-icon">◌</span><div><span class="eyebrow">CÁ NHÂN HÓA</span><h2>Chuyển động</h2></div></div><p>Chọn cảm giác tương tác phù hợp với bạn. Thay đổi được áp dụng ngay.</p><fieldset class="motion-options"><legend>Mức chuyển động</legend>${[['minimal','Minimal','Êm và ít chuyển động'],['balanced','Balanced','Mềm mại, cân bằng'],['playful','Playful','Sinh động hơn']].map(([id,name,desc])=>`<label class="motion-choice ${motion===id?'is-selected':''}"><input type="radio" name="motion-level" value="${id}" ${motion===id?'checked':''}><span class="choice-dot"></span><span><strong>${name}</strong><small>${desc}</small></span></label>`).join('')}</fieldset><div class="setting-note"><span>✳</span><p>Paper English cũng tôn trọng tùy chọn giảm chuyển động trên thiết bị của bạn.</p></div></section>${audioSettingsPanel()}<section class="paper setting-panel backup-panel"><div class="panel-heading"><span class="panel-icon peach-icon">↧</span><div><span class="eyebrow">DỮ LIỆU CỦA BẠN</span><h2>Giữ lại hành trình</h2></div></div><p>Bài học và tiến độ được lưu trên trình duyệt này. Hãy xuất bản sao lưu để lưu giữ hoặc chuyển sang thiết bị khác.</p><div class="backup-actions">${btn('↓ &nbsp; Xuất bản sao lưu','backup','dark')}<label class="button file-button">↑ &nbsp; Nhập bản sao lưu<input id="restore" type="file" accept="application/json" hidden></label></div><span class="storage-caption">◈ &nbsp; Lưu cục bộ trên thiết bị này</span></section></div><section class="paper playground"><div class="playground-header"><div><span class="eyebrow">INTERACTIVE PLAYGROUND</span><h2>Chạm để cảm nhận.</h2><p>Một không gian nhỏ để thử chất liệu giấy của bạn.</p></div><span class="playground-spark">✳</span></div><div class="playground-canvas"><div class="playground-card"><span class="eyebrow">PAPER CARD</span><strong>Nhẹ nhàng<br>mỗi ngày.</strong><span>Di chuột lên tấm giấy ↗</span></div><div class="playground-controls"><div class="play-row"><span>Nút giấy<small>Nhấn và thả</small></span><button class="button playground-button" data-action="play-press">Chạm vào tôi ↗</button></div><div class="play-row"><span>Công tắc<small>Thử bật và tắt</small></span><button class="play-switch ${state.playSwitch?'on':''}" data-action="play-switch" role="switch" aria-checked="${!!state.playSwitch}" aria-label="Công tắc thử nghiệm"><i></i></button></div><div class="play-row"><span>Mảnh từ<small>Chạm để chọn</small></span><button class="word play-word ${state.playWord?'selected-word':''}" data-action="play-word" aria-pressed="${!!state.playWord}">lovely ✦</button></div><div class="play-row"><span>Đáp án<small>Chạm để chọn</small></span><button class="play-answer ${state.playAnswer?'is-selected':''}" data-action="play-answer" aria-pressed="${!!state.playAnswer}"><b>A</b> Một lựa chọn <span>${state.playAnswer?'✓':'○'}</span></button></div></div></div><div class="playground-footer"><span class="mode-indicator">● &nbsp; ${motion.toUpperCase()}</span><p>${descriptions[motion]}</p></div></section></div>`}

let lastPage='',lastQuestion='';function render(){document.documentElement.dataset.motion=data.settings.motion;let page=state.page;let changed=page!==lastPage;let question=state.session&&!state.session.finished?state.session.kind+':'+state.session.index:'';let questionChanged=!!question&&question!==lastQuestion;let scope=page+':'+(state.session?.finished?'finished':state.session?.questions?.[state.session.index]?.id||'');if(audioScope&&scope!==audioScope)tts.stop();audioScope=scope;lastPage=page;lastQuestion=question;let content=page==='home'?home():page==='library'?library():page==='detail'?detail():page==='quiz'?quiz():page==='sentence'?sentence():page==='import'?importer():page==='stats'?statistics():page==='review'?review():settings();app.innerHTML=layout(content);if(changed&&matchMedia('(max-width:700px)').matches){let nav=app.querySelector('.sidebar nav'),active=nav?.querySelector('.active');if(active)nav.scrollLeft=active.offsetLeft-nav.offsetLeft-(nav.clientWidth-active.offsetWidth)/2}if(state.session?.finished&&!state.session.celebrated){state.session.celebrated=true;let el=app.querySelector('.result-score');if(el&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&data.settings.motion!=='minimal'){let target=parseInt(el.textContent,10),start=performance.now();function count(now){let t=Math.min(1,(now-start)/700);el.innerHTML=Math.round(target*(1-(1-t)**3))+'<span>%</span>';if(t<1&&el.isConnected)requestAnimationFrame(count)}requestAnimationFrame(count)}}if(changed)app.querySelector('main')?.classList.add('page-enter');if(questionChanged)app.querySelector('.question-content, .sentence-card')?.classList.add('question-enter');bindDrop();updateAudioUI()}
function go(page){state.page=page;render();window.scrollTo(0,0)}function syncInput(){let el=document.querySelector('#answer-input');if(el&&state.session){state.session.answers[state.session.questions[state.session.index].id]=el.value;persist()}}function finish(){let s=state.session;syncInput();for(let q of s.questions){let a=s.answers[q.id];if(a!==undefined&&String(a).trim()!=='')record(q,a,score(q,a))}s.finished=true;data.session=null;persist();render()}
function parseFile(file){if(!file)return;file.text().then(t=>{try{state.draft=parseCSV(t).map(rowQuestion);render();toast(`Đã đọc ${state.draft.length} câu. Hãy kiểm tra trước khi lưu.`)}catch(e){toast('Không đọc được CSV: '+e.message)}})}function bindDrop(){let z=document.querySelector('#upload-zone');if(z){z.ondragover=e=>{e.preventDefault();z.classList.add('dragging')};z.ondragleave=()=>z.classList.remove('dragging');z.ondrop=e=>{e.preventDefault();z.classList.remove('dragging');parseFile(e.dataTransfer.files[0])}}let az=document.querySelector('#answer-zone');if(az){az.ondragover=e=>e.preventDefault();az.ondragenter=()=>az.classList.add('drag-over');az.ondragleave=e=>{if(!az.contains(e.relatedTarget))az.classList.remove('drag-over')};az.ondrop=e=>{e.preventDefault();az.classList.remove('drag-over');let raw=e.dataTransfer.getData('text/plain');if(raw==='')return;let id=Number(raw),order=state.session.order,target=e.target.closest('[data-token-remove]');let at=target?order.indexOf(Number(target.dataset.tokenRemove)):order.length;let old=order.indexOf(id);if(old!==-1){order.splice(old,1);if(old<at)at--}order.splice(Math.max(0,at),0,id);persist();render()}}document.querySelectorAll('[data-drag-id]').forEach(el=>{el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.dragId);e.dataTransfer.effectAllowed='move';el.classList.add('drag-lift')};el.ondragend=()=>el.classList.remove('drag-lift')})}
app.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value;let pos=e.target.selectionStart;render();let x=document.querySelector('#search');x.focus();x.setSelectionRange(pos,pos)}if(e.target.id==='set-name')state.importName=e.target.value;if(e.target.id==='set-topic')state.importTopic=e.target.value;if(e.target.id==='answer-input')syncInput()});app.addEventListener('change',async e=>{let key=e.target.dataset.audioSetting;if(key){let cfg=audioConfig();cfg[key]=e.target.type==='checkbox'?e.target.checked:key==='rate'?Number(e.target.value):e.target.value;if(key==='accent')cfg.voice='';data.settings.audio=cfg;tts.stop();persist();render();return}if(e.target.id==='file')parseFile(e.target.files[0]);if(e.target.id==='filter'){state.filter=e.target.value;render()}if(e.target.name==='motion-level'){data.settings.motion=e.target.value;persist();render()}if(e.target.id==='restore'){try{let x=JSON.parse(await e.target.files[0].text());if(!Array.isArray(x.sets)||!Array.isArray(x.attempts))throw Error();if(confirm('Thay thế dữ liệu hiện tại bằng bản sao lưu này?')){data=x;data.settings||={motion:'balanced'};persist();go('home');toast('Đã khôi phục bản sao lưu.')}}catch{toast('Bản sao lưu không hợp lệ.')}}});
app.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-stop-audio')){tts.stop();return}if(b.dataset.speak){tts.speak(audioText(b.dataset.speak),audioConfig());return}if(b.dataset.page){go(b.dataset.page);return}if(b.dataset.open){state.detail=b.dataset.open;go('detail');return}if(b.dataset.tab){state.tab=b.dataset.tab;render();return}if(b.dataset.day){state.selectedDay=b.dataset.day;render();return}if(b.dataset.duplicate){let s=structuredClone(setBy(b.dataset.duplicate));s.id=uid();s.name+=' (bản sao)';s.demo=false;s.questions.forEach(q=>q.id=uid());data.sets.unshift(s);persist();render();return}if(b.dataset.delete){if(confirm('Xóa bộ đề này? Lịch sử học vẫn được giữ lại.')){data.sets=data.sets.filter(s=>s.id!==b.dataset.delete);persist();render()}return}if(b.dataset.removeQuestion){let s=setBy(state.detail);if(confirm('Xóa câu hỏi này?')){s.questions=s.questions.filter(q=>q.id!==b.dataset.removeQuestion);persist();render()}return}if(b.dataset.editQuestion||b.dataset.draftEdit!==undefined){let q=b.dataset.editQuestion?setBy(state.detail).questions.find(q=>q.id===b.dataset.editQuestion):state.draft[+b.dataset.draftEdit];let promptText=prompt('Câu hỏi:',q.prompt);if(promptText===null)return;let answer=prompt('Đáp án:',q.answer);if(answer===null)return;let explanation=prompt('Giải thích:',q.explanation);if(explanation===null)return;q.prompt=promptText;q.answer=answer;q.explanation=explanation;persist();render();return}if(b.dataset.draftDelete!==undefined){state.draft.splice(+b.dataset.draftDelete,1);render();return}if(b.dataset.review){let s=data.sets.find(s=>s.questions.some(q=>q.id===b.dataset.review)),q=s.questions.find(q=>q.id===b.dataset.review);state.page=q.type==='sentence'?'sentence':'quiz';start(s.id,state.page,[q]);return}let s=state.session;if(b.dataset.answer&&s){let q=s.questions[s.index],v=b.dataset.answer;if(q.type==='multi'){let a=s.answers[q.id]||[];s.answers[q.id]=a.includes(v)?a.filter(x=>x!==v):[...a,v]}else s.answers[q.id]=v;persist();render();return}if(b.dataset.jump!==undefined&&s){syncInput();s.index=+b.dataset.jump;s.questionStarted=Date.now();persist();render();return}if(b.dataset.tokenAdd!==undefined){s.order.push(+b.dataset.tokenAdd);persist();render();return}if(b.dataset.tokenRemove!==undefined){s.order=s.order.filter(x=>x!==+b.dataset.tokenRemove);persist();render();return}let a=b.dataset.action;if(!a)return;switch(a){case 'play-press':b.classList.remove('spring-pop');void b.offsetWidth;b.classList.add('spring-pop');break;case 'play-switch':state.playSwitch=!state.playSwitch;render();break;case 'play-word':state.playWord=!state.playWord;render();break;case 'play-answer':state.playAnswer=!state.playAnswer;render();break;case 'go-quiz':go('quiz');break;case 'go-import':state.appendTo=null;go('import');break;case 'go-library':go('library');break;case 'toggle-view':state.view=state.view==='card'?'list':'card';render();break;case 'start-detail':{let x=setBy(state.detail),qs=x.questions.filter(q=>q.type!=='sentence');if(qs.length){state.page='quiz';start(x.id,'quiz',qs)}else toast('Bộ đề này chưa có câu Quiz.');break}case 'add-detail':state.appendTo=state.detail;state.draft=[];go('import');break;case 'export-csv':download('paper-english.csv',toCSV(setBy(state.detail).questions),'text/csv;charset=utf-8');break;case 'export-set':download('paper-english-set.json',JSON.stringify(setBy(state.detail),null,2),'application/json');break;case 'sample-csv':download('paper-english-sample.csv',toCSV(demo.questions),'text/csv;charset=utf-8');break;case 'parse-text':state.draft=parseText(document.querySelector('#pasted').value);render();toast(`Đã phân tích ${state.draft.length} khối.`);break;case 'add-manual':{let q=rowQuestion({type:document.querySelector('#manual-type').value,question:document.querySelector('#manual-prompt').value,answer:document.querySelector('#manual-answer').value,option_a:document.querySelector('#opt-A').value,option_b:document.querySelector('#opt-B').value,option_c:document.querySelector('#opt-C').value,option_d:document.querySelector('#opt-D').value,explanation:document.querySelector('#manual-explanation').value});state.draft.push(q);render();break}case 'save-import':{if(!state.draft.length){toast('Hãy thêm ít nhất một câu hỏi.');break}if(state.draft.some(q=>validate(q).length)){toast('Hãy sửa các câu có lỗi trước khi lưu.');break}let name=state.importName?.trim();if(!state.appendTo&&!name){toast('Hãy đặt tên bộ đề.');break}if(state.appendTo)setBy(state.appendTo).questions.push(...state.draft);else data.sets.unshift({id:uid(),name,topic:state.importTopic||'Chưa phân loại',difficulty:document.querySelector('#set-difficulty').value,questions:state.draft});state.draft=[];state.appendTo=null;state.importName='';state.importTopic='';persist();go('library');toast('Đã lưu bộ đề.');break}case 'start-quiz':case 'start-sentence':{let id=document.querySelector('#set-choice').value,kind=a==='start-quiz'?'quiz':'sentence',qs=setBy(id).questions.filter(q=>kind==='quiz'?q.type!=='sentence':q.type==='sentence');if(kind==='quiz'){if(document.querySelector('#order').value==='random')qs.sort(()=>Math.random()-.5);qs=qs.slice(0,Math.max(1,Number(document.querySelector('#count').value)||10))}start(id,kind,qs,kind==='quiz'?document.querySelector('#mode').value:'practice');break}case 'resume':state.session=data.session;state.page=state.session.kind;render();break;case 'exit-session':data.session=s;persist();state.session=null;go('home');break;case 'mark':{let id=s.questions[s.index].id;s.marked=s.marked.includes(id)?s.marked.filter(x=>x!==id):[...s.marked,id];persist();render();break}case 'check':{syncInput();let q=s.questions[s.index],v=s.answers[q.id];if(v===undefined||String(v).trim()===''){toast('Hãy chọn hoặc nhập câu trả lời.');break}record(q,v,score(q,v));render();break}case 'prev':if(s.index>0){syncInput();s.index--;s.questionStarted=Date.now();persist();render()}break;case 'next':syncInput();if(s.index===s.questions.length-1)finish();else{s.index++;s.questionStarted=Date.now();persist();render()}break;case 'finish':if(confirm('Nộp bài và xem kết quả?'))finish();break;case 'close-result':state.session=null;go('home');break;case 'retry-wrong':{let qs=s.questions.filter(q=>s.answers[q.id]!==undefined&&!score(q,s.answers[q.id]));if(!qs.length){toast('Không có câu sai để làm lại.');break}start(s.setId,s.kind,qs,s.mode);break}case 'undo':s.order.pop();persist();render();break;case 'reset-words':s.order=[];persist();render();break;case 'hint':toast('Từ đầu tiên: '+s.questions[s.index].answer.split(/\s+/)[0]);break;case 'check-sentence':{let q=s.questions[s.index],v=s.order.map(id=>s.tokens.find(t=>t.id===id).word).join(' ');if(!v){toast('Hãy chọn các từ trước.');break}s.answers[q.id]=v;let correct=score(q,v);record(q,v,correct);render();if(correct&&audioConfig().autoPlay)tts.speak(q.answer,audioConfig());break}case 'next-sentence':if(s.index===s.questions.length-1)finish();else{s.index++;s.questionStarted=Date.now();persist();render()}break;case 'backup':download('paper-english-backup.json',JSON.stringify(data,null,2),'application/json');break}});
try{db=await openDB();let saved=await read();if(saved)data=saved;else{data.sets=[demo];await save()}data.settings||={motion:'balanced'};render()}catch(e){app.innerHTML='<div class="fatal">Không thể mở bộ nhớ trình duyệt. Vui lòng bật IndexedDB và tải lại trang.</div>'}


